new="""      - name: Restore PlatformIO dependencies\n        uses: actions/cache@v4\n        with:\n          path: |\n            ~/.platformio/platforms\n            ~/.platformio/packages\n            firmware/.pio/libdeps\n          key: ${{ runner.os }}-pio-v2-${{ hashFiles('firmware/platformio.ini', 'tools/requirements-build.txt') }}\n          restore-keys: |\n            ${{ runner.os }}-pio-v2-\n"""
if wf.count(old)!=1: raise SystemExit('compile workflow dependency cache anchor mismatch')
wf=wf.replace(old,new,1)
a="""      - name: Check audited delivery invariants\n        run: python tools/test_audit_fixes.py\n"""
if wf.count(a)!=1: raise SystemExit('compile workflow validation anchor mismatch')
wf=wf.replace(a,a+"""      - name: Check BLE connection and queue recovery\n        run: python tools/test_connection_recovery.py\n""",1)
c="""      - name: Compile NanoC6 firmware\n        run: pio run -d firmware -e m5stack-nanoc6 -j 4\n"""
d="""      - name: Compile NanoC6 firmware\n        run: pio run -d firmware -e m5stack-nanoc6 -j 4\n      - name: Capture linker diagnostics\n        run: |\n          set -euo pipefail\n          test -s firmware/.pio/build/m5stack-nanoc6/firmware.elf\n          test -s firmware/.pio/build/m5stack-nanoc6/firmware.map\n          mkdir -p build-diagnostics\n          cp firmware/.pio/build/m5stack-nanoc6/firmware.elf build-diagnostics/\n          cp firmware/.pio/build/m5stack-nanoc6/firmware.map build-diagnostics/\n      - name: Upload short-lived linker diagnostics\n        uses: actions/upload-artifact@v4\n        with:\n          name: Anderson-Linker-Diagnostics-v${{ steps.version.outputs.version }}\n          path: build-diagnostics/*\n          retention-days: 7\n          if-no-files-found: error\n"""
if wf.count(c)!=1: raise SystemExit('compile workflow compile anchor mismatch')
write('.github/workflows/compile-anderson-home-multi.yml',wf.replace(c,d,1))
replace('.github/scripts/anderson-cache-cleanup.sh','pio-v1 dependency cache and anderson-objects-v2 object cache;','pio-v2 scoped dependency cache and anderson-objects-v2 object cache;')
