repl='''const paintPreview=(e,t)=>{const a=qa("i",e);if(!a.length)return;const s=e.dataset.effect,p="Jump"===s?"j"+Math.floor(t/360):"Strobe"===s?"s"+Math.floor(t/240):"Breath"===s?"b"+Math.floor(t/40):"solid";if(e.dataset.previewPhase===p)return;e.dataset.previewPhase=p,a.forEach((e,t)=>{e.style.background=n[t],e.style.color=n[t],e.style.opacity="1",e.style.transform="scale(1)",e.style.filter="none"});if("Jump"===s){const e=n[Math.floor(t/360)%n.length];a.forEach(t=>{t.style.background=e,t.style.color=e,t.style.filter="brightness(1.2)"})}else if("Breath"===s){const e=.22+(Math.sin(t/430)+1)/2*.78;a.forEach(t=>{t.style.background="#45d9ff",t.style.color="#45d9ff",t.style.opacity=String(e),t.style.transform=`scale(${.78+.24*e})`,t.style.filter=`brightness(${.65+.7*e})`})}else if("Strobe"===s){const e=Math.floor(t/240),s=e%2==0,o=n[Math.floor(e/2)%n.length];a.forEach(e=>{e.style.background=o,e.style.color=o,e.style.opacity=s?"1":".04",e.style.transform=s?"scale(1.08)":"scale(.82)",e.style.filter=s?"brightness(1.45)":"brightness(.4)"})}else a.forEach(e=>{e.style.background="#45d9ff",e.style.color="#45d9ff",e.style.filter="brightness(1.15)"})},canAnimate=()=>!document.hidden&&!!window.andersonProfile,animate=e=>{raf=0;if(!canAnimate())return;const t=reduce.matches?0:e;previews.forEach(e=>{e.isConnected?e.offsetParent!==null&&paintPreview(e,t):previews.delete(e)}),reduce.matches||(raf=requestAnimationFrame(animate))},startAnimation=()=>{canAnimate()&&(reduce.matches?animate(0):raf||(raf=requestAnimationFrame(animate)))},stopAnimation=()=>{raf&&(cancelAnimationFrame(raf),raf=0)},sync=e=>'''
