main=text('firmware/src/main.cpp')
pat=r'  server\.on\("/api/ble/scan",HTTP_GET,\[\]\{\n    if\(!requireAdmin\(\)\)return;if\(ble\.connecting\(\)\)\{server\.send\(409,"text/plain","Bluetooth connection in progress\. Try scanning again shortly\."\);return;\}auto found=ble\.scan\(\);JsonDocument d;JsonArray a=d\["devices"\]\.to<JsonArray>\(\);for\(auto&f:found\)\{JsonObject x=a\.add<JsonObject>\(\);x\["name"\]=f\.name;x\["address"\]=f\.address;x\["rssi"\]=f\.rssi;\}String out;serializeJson\(d,out\);sendJson\(out\);\n  \}\);'
new='''  server.on("/api/ble/scan",HTTP_GET,[]{\n    if(!requireAdmin())return;if(ble.connecting()){server.send(409,"text/plain","Bluetooth connection in progress. Try scanning again shortly.");return;}JsonDocument d;std::vector<BleFound> found;if(ble.consumeScanResults(found)){d["scanning"]=false;JsonArray a=d["devices"].to<JsonArray>();for(auto&f:found){JsonObject x=a.add<JsonObject>();x["name"]=f.name;x["address"]=f.address;x["rssi"]=f.rssi;}String out;serializeJson(d,out);sendJson(out);return;}if(ble.scanInProgress()){d["scanning"]=true;String out;serializeJson(d,out);sendJson(out);return;}if(!ble.startScan()){server.send(409,"text/plain","Bluetooth scan could not start. Try again shortly.");return;}d["scanning"]=true;String out;serializeJson(d,out);sendJson(out,202);\n  });'''
out,n=re.subn(pat,new,main,count=1,flags=re.S)
if n!=1: raise SystemExit('BLE endpoint anchor mismatch')
write('firmware/src/main.cpp',out)

print('Anderson Home 3.1.40 audit bundle applied.')
